INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (80, 246, 'BOPP tape grade film', '../upload/image/20180826/20180826191402_20626.jpg', '<p><span style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''><span style="font-family:Tahoma;font-size:18px;"><span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">BOPP tape grade film clear jumbo roll</span></span><br/> <br/> <span style="color:#009900;font-size:18px;background-color:#FFFFFF;">This goods is used for manufacturing BOPP adhesive packing tape (jumbo roll size). Also for high quality tape uses .</span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">Specifications:</span></span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">1) Length: 4000, 4850, 6000m..</span></span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">2) Width: 500mm, 520mm, 980mm,1000mm, 1040mm, 1200mm, 1280mm, 1310mm,1600mm,1620,1800, 2000mm etc.</span></span><br/> <span style="color:#009900;font-size:18px;background-color:#FFFFFF;">3) Color: Transparence</span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;"><span style="color:#009900;">4) Thickness: 18,20,23,25,28,30,35</span><span style="color:#009900;"> microns and others</span></span></span><br/> <span arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="white-space: normal; color: rgb(58, 58, 58);" times="" verdana=""><span style="font-size:18px;color:#009900;">5) Packing: Using carton with pallets or as per customers'' requirements</span></span><br/> <span style="color:#009900;font-size:18px;background-color:#FFFFFF;">6) used to adhere water based acrylic liquid and manufactured as Bopp packing tape.</span></span></span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (80, 185, 'BOPP Film (3-75 microns)', '../upload/image/20180925/20180925220111_26191.jpg', '<p></p><p>BOPP Film (3-75 microns)</p> <p>BOPP film (BOPP FOIL) is a packing film with a superior mechanical nature, transparent and moisture proof formed through the processing of draft Bi-axially Oriented Polypropylene (BOPP) vertically and horizontally.<br/> BOPP film including BOPP plain film ( BOPP flower film,BOPP tape-grade film,BOPP clothes/bag-grade film,BOPP mini/smaller roll,BOPP anti-static film);BOPP tobacco film; BOPP heat sealable film;BOPP matte film; BOPP pearlized film;BOPP thermal film; BOPP capacitor film;BOPP Sheets; BOPP anti-fog film; BOPP micro/ macro perforated film; Metallized BOPP film (VMBOPP); BOPP tear tape;BOPP laser film and so on. Featuring details : <br/> Main Properties,High transparency and gloss<br/> High tensile strength,High grease barrier<br/> Excellent ink and coating adhesion,Low static electricity<br/> Superior thickness uniformity,Smooth rolling and neat ends of film rolls<br/> Specifications:Thickness:12-52 micron Width:350-1600 mm Length:1000-18000M<br/> BOPP film (Polypropylene film) is widely used for plain, lamination, matte and metalized films which are used for many different sorts selection of applications,such as carton box, flower, gift, food, confectionery, lamination,CD,DVD, VCD,cigarette,and box packaging, packing tape, etc according to its purpose such as printing, clothes, tape and laminating which are used for many different sorts of applications as the selection follow. Customized dimensions and specifications are available upon request.</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (80, 187, 'BOPP Film (Biaxial-Oriented Polypropylene Film)', '../upload/image/20180925/20180925220003_73635.jpg', '<p></p><p>BOPP Film (Biaxial-Oriented Polypropylene Film)</p> <p>BOPP film (Polypropylene Film, BOPP foil, BOPP paper) featuring its thickness,differenct thickness have its own applications, We manufactured 9 items of BOPP film base on the thickness. Additionally,BOPP film also featuring 4 prominent data:shrinkage, heat sealable,corona treated,transparent and so forth.</p> <p>1. 3UM (Microns) -12UM( Micron) BOPP film for capacitor use .<br/> 1.) Capacitor Polypropylene Film for Type M-PP/S-PP (4um--12um)<br/> 2.) Capacitor Polypropylene Rough Film Type RPP/RRPP (6um --18um)<br/> 2. 15UM (Microns) -52UM (Microns) plain BOPP film for printing &amp; lamination .<br/> 1.) 12UM BOPP glossy film and 15UM BOPP matte film<br/> 2.) Plain tape-grade BOPP film with corona treated .(thickness :23-28 microns) <br/> 3.) Plain bag-grade BOPP film with corona treated.(thickness :30-45 microns)<br/> 3. 18UM( Micron) -37UM( Micron) heat sealable BOPP film .<br/> 1.) Single(one) side heat sealable BOPP film with corona treated .(thickness :18-52 microns) <br/> 2.) Double(two) sides heat sealable BOPP film with corona treated.(thickness :18-52 microns)<br/> 4. BOPP cigarette (or tobacco ) packaging film for hard/soft packs <br/> 1.) Plain BOPP cigarette film with heat sealable .(thickness : 21-22 microns ) <br/> 2.) Half-shrinkage BOPP cigarette film with heat sealable (thickness: 20-21 microns)<br/> 3.) High-shrinkage BOPP cigarette film with heat sealable (thickness :20-21 microns)<br/> 5. 1.) BOPP pearlized film. (thickness: 25-40 microns)<br/> 2.) BOPP matte film with inner side matte and two sides corona treated.( thickness :12,15,18 microns)<br/> 6. BOPP flower wrapping film (BOPP foil or BOPP paper or superclear cellophane) in mini-roll,sheets and sleeves <br/> 7. Use BOPP basic film ,there are following popular BOPP-based coated films widely in common use . BOPP film coated water based acrylic adhesive ,EVA ,PVDC,Acrylic and so on.<br/> (thickness:35-65 microns)<br/> 1.) BOPP adhesive industry packaging tape . <br/> 2.) BOPP gloss/matte thermal laminating film .(thickness: 25-35 microns) 3.) PVDC coating film 4.) Acrylic coating film<br/> 8.VM-OPP (metallized BOPP film) in plain BOPP and hest sealable BOPP. (thickness:15-35 microns).<br/> 9. 1.) BOPP tear tape (thickness: 18-35 microns)<br/> 2.) BOPP laser film (thickness: 15-40 microns)<br/> 3.) PP tear clips <br/> As we know ,Parameter of BOPP film including: Thickness , Width ,Length , Inner core( paper tube) diameter , Outer diameter ,Package requirement ,Application , and so forth .<br/> As one of the largest professionally specialized BOPP manufacturers in China , we will do our best to meet your multi-demands.</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (80, 196, '12MICRONS BOPP GLOSSY FILM AND 15UM BOPP MATTE FILM', '../upload/image/20180925/20180925220019_33757.jpg', '<p></p><p>12MICRONS BOPP GLOSSY FILM AND 15UM BOPP MATTE FILM</p> <p>BOPP film wet-cold lamination (12MICRONS BOPP GLOSSY FILM AND 15UM BOPP MATTE FILM), non heat sealable,for paper lamination:<br/> Thickness of BOPP glossy and BOPP matte film: 12,15 Microns<br/> Roll width for BOPP glossy and BOPP matte film: 250mm-1500MM <br/> Length: 3000,4000,9000,12000M <br/> Package: carton and pallets.</p> <p><br/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (80, 244, 'Plain BOPP Film (Bi-axially Oriented PolyPropylene) For Printing And Lamination', '../upload/image/20180925/20180925220037_59018.jpg', '<p></p><div id="right_main"> <table border="0" cellpadding="0" cellspacing="1" class="ke-zeroborder" style="margin:0px auto;" width="100%"> <tbody> <tr> <td class="line_buttom_hui_xuxian" colspan="2"> <div class="hangju" style="padding:3px;"> <p align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Plain BOPP Film (Bi-axially Oriented PolyPropylene) For Printing And Lamination</span></span></p> <p><span style="font-size:16px;"><span style=''font-family:"";''><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP film is widely used for plain, lamination, matte and metalized films which are used for many different sorts selection of applications, such as carton box, flower, gift, food, confectionery, lamination, CD, DVD, VCD, cigarette, and box packaging, packing tape, etc according to its purpose such as printing, clothes, tape and laminating which are used for many different sorts of applications as the selection follow.</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP film is a packing film with a superior mechanical nature, transparent and moisture proof formed through the processing of draft Bi-axially Oriented Polypropylene (BOPP) vertically and horizontally.</span></span></span></p> <table border="1" width="94%"> <tbody> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Parameter</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Value</span></span> </div> </td> </tr> <tr> <td width="32%"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Thickness</span></span> </div> </td> <td width="68%"> <p align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">10UM, 12UM ,15UM,18UM for lamination ,</span></span></p> <p align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">20UM, 23UM ,25UM,28UM,30UM,35-52UM for printing ,</span></span></p> <p align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">23UM ,25UM,28UM for adhesive tape''s basic material ,</span></span></p> <p align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">35UM,37UM,40UM,50UM for BOPP Bag''s basic material,</span></span></p> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Width</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">350MM-1600MM</span></span> </div> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Length</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">2000M ,3000M ,4000M ,7000M,8000M,9000M</span></span> </div> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Corona treated side</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Single(one) side or double (two)sides</span></span> </div> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Heat sealable</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Non-heatsealable</span></span> </div> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Application</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Printing, lamination , Aluminium metallization and so forth</span></span> </div> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Color</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Transparent ,clear</span></span> </div> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Inner core</span></span> </div> </td> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">76 mm(3'') ,152mm(6'')</span></span> </div> </td> </tr> <tr> <td> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Package method</span></span> </div> </td> <td> <div align="center"> <span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">Use carton with Bubble film around rolls</span><br/> <span style="font-family:Tahoma;font-size:18px;">and (wooden or plastic) pallets</span></span></span> </div> </td> </tr> <tr> <td height="235"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Loading details</span></span> </div> </td> <td> <div align="center"> <p align="left"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">1.Use 20GP ,40GP ,40HQ .</span></span></p> <p align="left"> <span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">2. Per 20GP . With pallets , can load 12-15 tons . If the width of the roll is less than 500MM (such as 350MM) ,can load 12 tons , otherwise ,width of the roll is more than 500MM (such as 900MM ) can load about 15 tons . Without pallets , per 20GP can load 16-18 tons , of course the width of the roll is the key for the quantity loading under the same case .</span><br/> <span style="font-family:Tahoma;font-size:18px;">3. Per 40GP ,With pallets(usually use 40HQ ), can load 24-25 tons . If the width of the roll is less than 500MM (such as 350MM) ,can load 24 tons , otherwise ,width of the roll is more than 500MM (such as 900MM ) can load around 25 tons . Without pallets , per 40GP can load 26-27 tons , of course the width of the roll is the key for the quantity loading under the same case .</span></span></span></p> </div> </td> </tr> </tbody> </table> <p><span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">Featuring details :</span><br/> <span style="font-family:Tahoma;font-size:18px;">Main Properties</span><br/> <span style="font-family:Tahoma;font-size:18px;">High transparency and gloss</span><br/> <span style="font-family:Tahoma;font-size:18px;">High tensile strength</span><br/> <span style="font-family:Tahoma;font-size:18px;">High grease barrier</span><br/> <span style="font-family:Tahoma;font-size:18px;">Excellent ink and coating adhesion</span><br/> <span style="font-family:Tahoma;font-size:18px;">Low static electricity</span><br/> <span style="font-family:Tahoma;font-size:18px;">Superior thickness uniformity</span><br/> <span style="font-family:Tahoma;font-size:18px;">Smooth rolling and neat ends of film rolls</span><br/> <span style="font-family:Tahoma;font-size:18px;">Specifications</span><br/> <span style="font-family:Tahoma;font-size:18px;">Thickness:12～52 micron</span><br/> <span style="font-family:Tahoma;font-size:18px;">Width:350～1600 mm</span><br/> <span style="font-family:Tahoma;font-size:18px;">Customized dimensions and specifications are available upon request.</span></span></span></p> <p><span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Tech Data ( Physical Properties) For Customer Reference :</span></span></p> <p align="center"> <span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">BOPP PLAIN FILM</span><br/> <span style="font-family:Tahoma;font-size:18px;">Standard : GB/T1003-96.</span></span></span></p> <p align="left"> <span style="font-size:16px;"><span style=''font-family:"";''><br/> <span style="font-family:Tahoma;font-size:18px;">1、Machinability</span></span></span></p> <table border="1" width="96%"> <tbody> <tr> <td width="27%"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Items</span></span> </div> </td> <td width="22%"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Prime</span></span> </div> </td> <td width="14%"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Eligible</span></span> </div> </td> <td width="11%"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Weak</span></span> </div> </td> <td width="15%"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">Test method</span></span> </div> </td> <td width="11%"> <div align="center"> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Taho