INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (80, 247, 'BOPP Film (Biaxial-Oriented Polypropylene Film)', '../upload/image/20180925/20180925215949_29294.jpg', '<p></p><p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">BOPP Film (Biaxial-Oriented Polypropylene Film)</span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">BOPP film is the most &amp; important popular plastic packaging material in modern times. It is widely used in packaging industry ,such as printing, lamination and Aluminium metallization .Also there are lots production lines of BOPP film all over the world ,As the largest developing market---China market , which has more than 200 BOPP lines . As one of the largest manufacturer of BOPP film , we warmly welcome you come to us for cooperation and place your order to us .</span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">BOPP film (Biaxial-oriented Polypropylene film) production line consists of casting</span><br/> <span style="font-family:Tahoma;font-size:18px;">sheet extrusion, biaxial orientation, after treatment, rolling, cutting, and automatic</span><br/> <span style="font-family:Tahoma;font-size:18px;">control. It can produce BOPP films of various specifications and stable dimensions,</span><br/> <span style="font-family:Tahoma;font-size:18px;">with good mechanical and electrical performances, good heat resistance, cold resistance</span><br/> <span style="font-family:Tahoma;font-size:18px;">and gastightness.</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP film featuring its thickness , differenct thickness have its own applications , We could manufacture 5 items of BOPP film base on the thickness . Additionally , BOPP film also featuring 4 prominent data : shrinkage , heat sealable , corona treated ,transparent and so forth .</span><br/> <span style="font-family:Tahoma;font-size:18px;">1. </span><br/> <span style="font-family:Tahoma;font-size:18px;">3UM (Microns) -12UM( Micron) BOPP film for capacitor use .</span><br/> <span style="font-family:Tahoma;font-size:18px;">1.) Capacitor Polypropylene Film for Type M-PP/S-PP (4um--12um )</span><br/> <span style="font-family:Tahoma;font-size:18px;">2.) Capacitor Polypropylene Rough Film Type RPP/RRPP (6um --18um)</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">2. </span><br/> <span style="font-family:Tahoma;font-size:18px;">15UM (Microns) -52UM (Microns) plain BOPP film for printing &amp; lamination .</span><br/> <span style="font-family:Tahoma;font-size:18px;">1.) Plain tape-grade BOPP film with corona treated .( thickness :23-28 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">2.) Plain bag-grade BOPP film with corona treated.( thickness :30-45 microns )</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">3.</span><br/> <span style="font-family:Tahoma;font-size:18px;">18UM( Micron) -37UM( Micron) heat sealable BOPP film .</span><br/> <span style="font-family:Tahoma;font-size:18px;">1.) Single(one) side heat sealable BOPP film with corona treated .( thickness :18-52 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">2.) Double(two) sides heat sealable BOPP film with corona treated.( thickness :18-52 microns )</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">4. </span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP cigarette (or tobacco ) packaging film for hard/soft packs </span><br/> <span style="font-family:Tahoma;font-size:18px;">1.) Plain BOPP cigarette film with heat sealable .(thickness : 21-22 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">2.) Half-shrinkage BOPP cigarette film with heat sealable ( thickness: 20-21 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">3.) High-shrinkage BOPP cigarette film with heat sealable ( thickness :20-21 microns )</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style=''font-family:"";''><span style="font-family:Tahoma;font-size:18px;">5.</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP pearlized film . ( thickness: 25-40 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP matte film with inner side matte and two sides corona treated .( thickness :12,15,18 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">6.</span><br/> <span style="font-family:Tahoma;font-size:18px;">BOPP flower film in mini-roll ,sheets and sleeves .</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">7.</span><br/> <span style="font-family:Tahoma;font-size:18px;">Use BOPP basic film ,there are following popular BOPP-based coated films widely in common use . BOPP film coated water based acrylic adhesive ,EVA ,PVDC and so on.</span><br/> <span style="font-family:Tahoma;font-size:18px;">( thickness:35-65 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">1.) BOPP adhesive industry packaging tape . </span><br/> <span style="font-family:Tahoma;font-size:18px;">2.) BOPP gloss/matte thermal laminating film .( thickness: 25-35 microns )</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">8.</span><br/> <span style="font-family:Tahoma;font-size:18px;">1.) VM-OPP( metallized BOPP film ). ( thickness:15-35 microns ).</span><br/> <span style="font-family:Tahoma;font-size:18px;">2.) BOPP laser film . ( thickness: 25-40 microns )</span><br/> <span style="font-family:Tahoma;font-size:18px;">3.) BOPP tear tape. ( thickness: 50-75 microns )</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">As we know ,Parameter of BOPP film including: Thickness , Width ,Length , Inner core( paper tube) diameter , Outer diameter ,Package requirement ,Application , and so forth .</span></span></span></p> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">As one of the largest professionally specialized BOPP manufacturers in China , we will do our best to meet your mult-demands.</span></span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (80, 427, 'BOPP ANTI STATIC FILM', '../upload/image/20211220/20211220142315_11653.jpg', '<p><span style="font-family:Tahoma;font-size:18px;color:#009900;">BOPP ANTI STATIC FILM</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">BOPP anti static film is used for packing textile relative goods,and it won''t stickup dust and atomy, and if your paste this sheets film on the wall , it won''t stay on the wall , it will slip from the wall.</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">thickness : 25-38microns.</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">width: 150,300,400,500,650,700,750,800,850,900,950,1050 mm....</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">length: 2000,300,4000,6000m,8000,12000,m...</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">packing: every roll of bopp film is packed by special packing paper, pe mat and pe stuff. the thickness must be equal and the surface should be flat.</span><br/> <br/></p>', '2026-09-06 20:58:45');
